      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "strokeColor": "#0877a6",
        "rx": 3
      }
    },
    "viz_sankey": {
      "type": "splunk.sankey",
      "dataSources": {
        "primary": "ds_sankey"
      },
      "title": "Sourcetype Mapping",
      "options": {
        "backgroundColor": "transparent"
      },
      "showLastUpdated": false,
      "showProgressBar": false
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/platform/#host-details",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_kpi_volume": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | eval bytes=len(_raw) | timechart span=1d sum(bytes) as bytes | eval daily=round(bytes/1048576, 1) | fields _time daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total | eval total=case(total>=1024, round(total/1024, 2).\" GB\", true(), round(total,1).\" MB\")",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_kpi_stcount": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | timechart span=1d dc(sourcetype) as daily | eventstats max(daily) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_kpi_errors": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ (log_level IN (ERROR, CRITICAL, FATAL) OR severity IN (ERROR, CRITICAL) OR is_critical=true) | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_kpi_auth": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ ((sourcetype=linux_secure (\"authentication failure\" OR \"Failed password\")) OR (sourcetype=\"sap:hana:audit\" action_category=auth result=FAILED) OR (sourcetype=XmlWinEventLog* EventCode IN (4625, 4771, 4776))) | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_event_count": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$\n| fields source, sourcetype, host\n| timechart span=1d count by sourcetype",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | eval sev=coalesce(log_level, severity, \"Info\") | eval sev=case(is_critical==\"true\" OR is_critical==true, \"Critical\", match(sev, \"(?i)crit|fatal|emerg|alert\"), \"Critical\", match(sev, \"(?i)error|err\\b\"), \"Error\", match(sev, \"(?i)warn\"), \"Warning\", true(), \"Info\") | timechart count by sev",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_host_inventory": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=linux_messages_syslog osqueryd | rex field=_raw \"cpu_brand: (?<cpu_brand>[^,]+)\" | rex field=_raw \"cpu_logical_cores: (?<cpu_cores>[^,]+)\" | rex field=_raw \"physical_memory: (?<phys_mem>[^,]+)\" | rex field=_raw \"hardware_model: (?<hw_model>[^,]+)\" | rex field=_raw \"pretty_name: (?<os_name>[^,]+)\" | rex field=_raw \"region: (?<aws_region>[^,]+)\" | rex field=_raw \"zone: (?<aws_az>[^,]+)\" | rex field=_raw \"id: (?<instance_id>i-[a-f0-9]+)\" | where isnotnull(cpu_brand) | eval memory_gb=round(phys_mem/1073741824,1).\" GB\" | stats latest(cpu_brand) as CPU latest(cpu_cores) as Cores latest(memory_gb) as RAM latest(hw_model) as \"Instance Type\" latest(os_name) as \"Operating System\" latest(aws_region) as Region latest(aws_az) as AZ latest(instance_id) as \"Instance ID\" by host | rename host as Host",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_recent_auth": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ ((sourcetype=linux_secure (\"Accepted\" OR \"Failed password\" OR \"authentication failure\" OR \"session opened\" OR \"session closed\")) OR (sourcetype=\"sap:hana:audit\" action_category=auth) OR (sourcetype=XmlWinEventLog* EventCode IN (4624, 4625, 4634, 4648, 4672, 4771, 4776))) | eval layer=case(sourcetype==\"linux_secure\", \"Linux\", sourcetype==\"sap:hana:audit\", \"HANA\", like(sourcetype, \"XmlWinEventLog%\"), \"Windows\", true(), sourcetype) | eval user=coalesce(user_name, user, Account_Name, \"-\") | eval result=case(sourcetype==\"sap:hana:audit\", result, match(_raw, \"(?i)Accepted|session opened|logon\"), \"success\", match(_raw, \"(?i)Failed|failure|denied|4625|4771\"), \"failed\", true(), \"-\") | eval client=coalesce(client_ip, src_ip, Source_Network_Address, \"-\") | eval action=case(sourcetype==\"sap:hana:audit\", action, match(_raw, \"(?i)Accepted\"), \"login\", match(_raw, \"(?i)session opened\"), \"session open\", match(_raw, \"(?i)session closed\"), \"session close\", match(_raw, \"(?i)Failed password\"), \"failed login\", match(_raw, \"(?i)authentication failure\"), \"auth failure\", true(), \"auth event\") | sort -_time | head 25 | table _time layer user action result client | rename _time as Time, layer as Layer, user as User, action as Action, result as Result, client as Client",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_recent_errors": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ (log_level IN (ERROR, CRITICAL, FATAL) OR severity IN (ERROR, CRITICAL) OR is_critical=true) | eval sev=coalesce(log_level, severity, \"-\") | eval comp=coalesce(component, process, source, \"-\") | eval msg=substr(_raw, 1, 180) | sort -_time | head 25 | table _time sourcetype sev comp msg | rename _time as Time, sourcetype as Sourcetype, sev as Severity, comp as Component, msg as Message",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_top_sources": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | stats count by source | sort -count | head 15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_hourly": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | eval hour=strftime(_time, \"%H\") | stats count by hour | sort hour",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_freshness": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ | stats count as Events, max(_time) as latest, min(_time) as first_seen by sourcetype | eval age_min=round((now()-latest)/60, 0) | eval Status=case(age_min<30, \"Fresh\", age_min<120, \"Stale\", true(), \"Very Stale\") | eval \"Last Seen\"=strftime(latest, \"%Y-%m-%d %H:%M:%S\") | eval \"First Seen\"=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\") | eval \"Age (min)\"=age_min | sort -Events | table sourcetype Events Status \"Age (min)\" \"Last Seen\" \"First Seen\" | rename sourcetype as Sourcetype",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_hana_audit": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=\"sap:hana:audit\" | top limit=15 action_type",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_abap_wp": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=\"sap:abap:workprocess\" | fields wp_category_name | stats count by wp_category_name | sort -count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_webdisp": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=\"sap:webdispatcher:access\" | eval status_class=case(status<300, \"2xx OK\", status<400, \"3xx Redirect\", status<500, \"4xx Client Error\", true(), \"5xx Server Error\") | timechart count by status_class",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_router": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=\"sap:saprouter\" | stats count as connections by peer_ip | sort -connections | head 15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_win": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=XmlWinEventLog* | top limit=15 EventCode",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_sudo": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=linux_messages_syslog sudo \"COMMAND=\" | rex field=_raw \"sudo(?:\\[\\d+\\])?:\\s+(?<invoking_user>\\S+)\\s*:\\s*TTY=\" | rex field=_raw \"USER=(?<target_user>\\S+)\\s*;\\s*COMMAND=\" | rex field=_raw \"COMMAND=(?<cmd>[^\\n]+)\" | eval cmd=substr(cmd, 1, 120) | stats count by invoking_user, target_user, cmd | sort -count | head 15 | rename invoking_user as User, target_user as \"As User\", cmd as Command, count as Count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_dns": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$ sourcetype=\"isc:bind:query\" | top limit=20 query",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_host_list": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` | stats count by host | fields host | rename host AS label | eval value=label | sort label",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_sankey": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` host=$host_name$\n| fields source, sourcetype, host\n| stats count by sourcetype, source",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "latest": "$global_time.latest$",
            "earliest": "$global_time.earliest$"
          }
        }
      }
    }
  },
